<?php use Sipe\Middleware\Security; function selectRows(string $name,string $label,array $list): void { ?><label><?= e($label) ?><select name="<?= e($name) ?>" required><option value="">Seleccionar</option><?php foreach($list as $item): ?><option value="<?= e($item['id']) ?>"><?= e($item['nombre']) ?></option><?php endforeach ?></select></label><?php } function conditionFields(): void { ?><label>Estado físico<select name="estado_fisico" required><option value="BUENO">Bueno</option><option value="REGULAR">Regular</option><option value="DANADO">Dañado</option></select></label><label>Observaciones<textarea name="observaciones" maxlength="5000" rows="3"></textarea></label><?php } ?>
<div class="page-heading"><div><span class="eyebrow">PANEL PRÉSTAMOS</span><h1><?= e($title) ?></h1><p class="muted">Cada movimiento conserva su responsable y su historial.</p></div></div>
<section class="card"><h2><?= $route==='reservations'?'Nueva reserva':($route==='loans'?'Registrar entrega':'Inspección periódica') ?></h2><form method="post" data-confirm="¿Confirmar el registro de esta operación?"><input type="hidden" name="csrf" value="<?= e(Security::token()) ?>"><input type="hidden" name="action" value="<?= $route==='reservations'?'reserve':($route==='loans'?'lend':'inspect') ?>"><div class="form-grid"><?php if($route!=='inspections'){selectRows('estudiante_id','Estudiante',$students);}selectRows('recurso_id','Recurso',$resources); ?>
<?php if($route==='reservations'): ?><label>Inicio<input name="inicio" type="datetime-local" required></label><?php endif ?><?php if($route!=='inspections'): ?><label>Fecha y hora límite<input name="fin" type="datetime-local" required></label><?php endif ?><?php if($route==='loans'): ?><label>Reserva vinculada (opcional)<input name="reserva_id" type="number" min="1"></label><?php endif ?><?php if($route!=='reservations'){conditionFields();} ?><?php if($route==='inspections'): ?><label>Apto para préstamo<select name="apto"><option value="1">Sí</option><option value="0">No, requiere mantenimiento</option></select></label><?php endif ?></div><button>Confirmar <?= $route==='reservations'?'reserva':($route==='loans'?'entrega':'inspección') ?></button></form></section>
<?php if($route==='loans'): ?><section class="card"><h2>Registrar devolución</h2><form method="post" data-confirm="¿Confirmar la devolución? El movimiento quedará cerrado."><input type="hidden" name="csrf" value="<?= e(Security::token()) ?>"><input type="hidden" name="action" value="return"><div class="form-grid"><label>Préstamo activo<select name="prestamo_id" required><option value="">Seleccionar</option><?php foreach($rows as $p): if($p['estado']!=='ACTIVO')continue; ?><option value="<?= e($p['id']) ?>">#<?= e($p['id'].' · '.$p['estudiante'].' · '.$p['recurso']) ?></option><?php endforeach ?></select></label><?php conditionFields() ?><label>Apto para préstamo<select name="apto"><option value="1">Sí</option><option value="0">No, requiere mantenimiento</option></select></label></div><button>Confirmar devolución</button></form></section><?php endif ?>
<section class="card"><h2>Historial · últimos 100 registros</h2><?php if($route==='reservations'): ?><div class="table-wrap"><table><thead><tr><th>Reserva</th><th>Estudiante / recurso</th><th>Intervalo</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td>#<?= e($row['id']) ?></td><td><?= e($row['estudiante'].' / '.$row['recurso']) ?></td><td><?= e($row['inicio'].' → '.$row['fin']) ?></td><td><?= e($row['estado']) ?></td><td><?php if($row['estado']==='CONFIRMADA'): ?><form method="post" data-confirm="¿Cancelar esta reserva?"><input type="hidden" name="csrf" value="<?= e(Security::token()) ?>"><input type="hidden" name="action" value="cancel"><input type="hidden" name="id" value="<?= e($row['id']) ?>"><button class="secondary">Cancelar</button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php else: require ROOT.'/app/Views/table.php';endif ?></section>
